#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <linux/loop.h>
#include <poll.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/prctl.h>
#include <sys/stat.h>
#include <sys/sysmacros.h>
#include <sys/vfs.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

#define CG "/sys/fs/cgroup/unified/refault"
#define BLK "/sys/fs/cgroup/blkio/refault"
#define HOT_BYTES (2*1024*1024)
#define ANCHOR_BYTES (12*1024*1024)
#define CHURN_BYTES (48*1024*1024)
#define IMAGE "/refault.ext4"
#define DEVICE "/dev/loop3"
static pid_t child;
static int expected_hooks;
struct pressure { unsigned long long some, full; };
struct stats { unsigned long long refault,activate,active,deactivate,pgscan,pgsteal,max_event; };
struct prepared { unsigned resident,warmed_resident; unsigned long churn_bytes; struct stats stats; };
static void cleanup(void) { if(child>0){kill(child,SIGKILL);while(waitpid(child,NULL,0)<0&&errno==EINTR){}child=0;} }
static void ck(int ok,const char *name){if(!ok){fprintf(stderr,"LAB_REFAULT_FAILED %s errno=%d (%s)\n",name,errno,strerror(errno));cleanup();exit(1);}}
static void watchdog(int sig){(void)sig;if(child>0)kill(child,SIGKILL);static const char m[]="LAB_REFAULT_FAILED watchdog\n";(void)write(2,m,sizeof(m)-1);_exit(124);}
static double now(void){struct timespec ts;ck(!clock_gettime(CLOCK_MONOTONIC,&ts),"clock");return ts.tv_sec+ts.tv_nsec/1e9;}
static void put(const char *p,const char *v){int fd=open(p,O_WRONLY|O_CLOEXEC);ck(fd>=0,p);ssize_t n=write(fd,v,strlen(v));int e=errno;close(fd);errno=e;ck(n==(ssize_t)strlen(v),p);}
static void group_put(const char *g,const char *f,const char *v){char p[256];snprintf(p,sizeof(p),"%s/%s",g,f);put(p,v);}
static void enter(const char *g){char v[32];snprintf(v,sizeof(v),"%d",getpid());group_put(g,"cgroup.procs",v);}
static void read_exact(int fd,void *p,size_t length){size_t got=0;while(got<length){ssize_t n=read(fd,(char *)p+got,length-got);if(n<0&&errno==EINTR)continue;ck(n>0,"control pipe read");got+=(size_t)n;}}
static struct pressure pressure(const char *g,const char *resource){char path[256],line[256],kind[8];snprintf(path,sizeof(path),"%s/%s.pressure",g,resource);FILE *f=fopen(path,"r");ck(f!=NULL,path);struct pressure p={0};int mask=0;while(fgets(line,sizeof(line),f)){double a,b,c;unsigned long long n;ck(sscanf(line,"%7s avg10=%lf avg60=%lf avg300=%lf total=%llu",kind,&a,&b,&c,&n)==5,"pressure format");if(!strcmp(kind,"some")){p.some=n;mask|=1;}else if(!strcmp(kind,"full")){p.full=n;mask|=2;}else ck(0,"pressure kind");}fclose(f);ck(mask==3,"some/full pressure");return p;}
static struct stats stats(const char *g){char path[256],key[80];unsigned long long n;struct stats s={0};snprintf(path,sizeof(path),"%s/memory.stat",g);FILE *f=fopen(path,"r");ck(f!=NULL,path);while(fscanf(f,"%79s %llu",key,&n)==2){if(!strcmp(key,"workingset_refault"))s.refault=n;else if(!strcmp(key,"workingset_activate"))s.activate=n;else if(!strcmp(key,"active_file"))s.active=n;else if(!strcmp(key,"pgdeactivate"))s.deactivate=n;else if(!strcmp(key,"pgscan"))s.pgscan=n;else if(!strcmp(key,"pgsteal"))s.pgsteal=n;}fclose(f);snprintf(path,sizeof(path),"%s/memory.events",g);f=fopen(path,"r");ck(f!=NULL,path);while(fscanf(f,"%79s %llu",key,&n)==2)if(!strcmp(key,"max"))s.max_event=n;fclose(f);return s;}
static int trigger(const char *g,const char *resource){char path[256];snprintf(path,sizeof(path),"%s/%s.pressure",g,resource);int fd=open(path,O_RDWR|O_NONBLOCK|O_CLOEXEC);ck(fd>=0,path);static const char spec[]="some 20000 500000";ck(write(fd,spec,sizeof(spec))==sizeof(spec),"register threshold");return fd;}
static int notified(int fd,int timeout,const char *name){struct pollfd p={.fd=fd,.events=POLLPRI};int n=poll(&p,1,timeout);ck(n>=0,"poll pressure");if(n){ck((p.revents&POLLPRI)&&!(p.revents&(POLLERR|POLLHUP|POLLNVAL)),name);printf("LAB_REFAULT_EVENT %s flags=0x%x\n",name,p.revents);}return n;}
static void throttle(int enabled){struct stat st;ck(!stat(DEVICE,&st),"loop number");char v[80];snprintf(v,sizeof(v),"%u:%u %d",major(st.st_rdev),minor(st.st_rdev),enabled?524288:0);put(BLK "/blkio.throttle.read_bps_device",v);}
static void read_file(int fd,size_t length){unsigned char buf[65536];for(size_t p=0;p<length;p+=sizeof(buf)){size_t n=length-p;if(n>sizeof(buf))n=sizeof(buf);ck(pread(fd,buf,n,(off_t)p)==(ssize_t)n,"buffered file read");for(size_t i=0;i<n;i++)ck(buf[i]==0xa5,"file data");}}
static unsigned residency(void *mapping,size_t length){unsigned char bits[ANCHOR_BYTES/4096];ck(length/4096<=sizeof(bits),"mincore bound");ck(!mincore(mapping,length,bits),"mincore");unsigned count=0;for(size_t i=0;i<length/4096;i++)count+=!!(bits[i]&1);return count;}
static void touch_anchor(volatile unsigned char *mapping){volatile unsigned sum=0;for(size_t p=0;p<ANCHOR_BYTES;p+=4096)sum+=mapping[p];(void)sum;}
static struct prepared prepare_hot(void){int hot=open("/files/hot",O_RDONLY),anchor=open("/files/anchor",O_RDONLY),churn=open("/files/churn",O_RDONLY);ck(hot>=0&&anchor>=0&&churn>=0,"open hot preparation files");void *hotmap=mmap(NULL,HOT_BYTES,PROT_READ,MAP_SHARED,hot,0);volatile unsigned char *amap=mmap(NULL,ANCHOR_BYTES,PROT_READ,MAP_SHARED,anchor,0);ck(hotmap!=MAP_FAILED&&(void *)amap!=MAP_FAILED,"map mincore and anchor");for(int i=0;i<3;i++){read_file(hot,HOT_BYTES);read_file(anchor,ANCHOR_BYTES);}touch_anchor(amap);struct prepared p={.warmed_resident=residency(hotmap,HOT_BYTES)};ck(p.warmed_resident==HOT_BYTES/4096,"hot fully warm before eviction");struct stats warm=stats(CG "/hot");printf("LAB_REFAULT_WARM active_file=%llu hot_resident=%u\n",warm.active,p.warmed_resident);unsigned char buf[65536];for(size_t off=0;off<CHURN_BYTES;off+=sizeof(buf)){ck(pread(churn,buf,sizeof(buf),(off_t)off)==sizeof(buf),"bounded churn read");p.churn_bytes=off+sizeof(buf);if((off+sizeof(buf))%(256*1024)==0){touch_anchor(amap);p.resident=residency(hotmap,HOT_BYTES);if(p.resident<=HOT_BYTES/4096/8)break;}}p.resident=residency(hotmap,HOT_BYTES);p.stats=stats(CG "/hot");printf("LAB_REFAULT_PREPARED resident=%u churn_bytes=%lu active_file=%llu pgdeactivate=%llu pgscan=%llu pgsteal=%llu max_events=%llu\n",p.resident,p.churn_bytes,p.stats.active,p.stats.deactivate,p.stats.pgscan,p.stats.pgsteal,p.stats.max_event);ck(p.resident<=HOT_BYTES/4096/8,"real hot eviction while keeping shadow");ck(p.stats.deactivate>0&&p.stats.pgsteal>0,"LRU aging and eviction occurred");munmap(hotmap,HOT_BYTES);munmap((void *)amap,ANCHOR_BYTES);close(hot);close(anchor);close(churn);return p;}
static void worker(const char *g,int hot,int gate,int ready){signal(SIGALRM,SIG_DFL);alarm(50);ck(!prctl(PR_SET_PDEATHSIG,SIGKILL),"child death signal");enter(g);enter(BLK);struct prepared p={0};if(hot)p=prepare_hot();else{int fd=open("/files/cold",O_RDONLY);ck(fd>=0,"cold file");void *map=mmap(NULL,HOT_BYTES,PROT_READ,MAP_SHARED,fd,0);ck(map!=MAP_FAILED,"cold map");p.resident=residency(map,HOT_BYTES);ck(p.resident==0,"cold file has no resident cache pages");munmap(map,HOT_BYTES);close(fd);}ck(write(ready,&p,sizeof(p))==sizeof(p),"preparation ready");close(ready);char c;read_exact(gate,&c,1);close(gate);int fd=open(hot?"/files/hot":"/files/cold",O_RDONLY);ck(fd>=0,"measurement file");double start=now();read_file(fd,HOT_BYTES);printf("LAB_REFAULT_READ kind=%s seconds=%.3f bytes=%d\n",hot?"hot":"cold",now()-start,HOT_BYTES);close(fd);_exit(0);}
static void run_phase(int hot){const char *g=hot?CG "/hot":CG "/cold";ck(!mkdir(g,0700),"phase cgroup");group_put(g,"memory.max",hot?"20971520":"134217728");group_put(g,"memory.high","max");int gate[2],ready[2];ck(!pipe2(gate,O_CLOEXEC)&&!pipe2(ready,O_CLOEXEC),"phase pipes");throttle(0);child=fork();ck(child>=0,"fork file worker");if(!child){close(gate[1]);close(ready[0]);worker(g,hot,gate[0],ready[1]);}close(gate[0]);close(ready[1]);struct prepared prepared;read_exact(ready[0],&prepared,sizeof(prepared));close(ready[0]);group_put(g,"memory.max","134217728");throttle(1);int mem=trigger(g,"memory"),io=trigger(g,"io");struct stats before=stats(g);struct pressure mem_before=pressure(g,"memory"),io_before=pressure(g,"io");double began=now();ck(write(gate[1],"x",1)==1,"start measurement");close(gate[1]);ck(notified(io,6000,hot?"hot_io":"cold_io"),"file IO notification");int memory_event=0;if(hot&&expected_hooks)memory_event=notified(mem,6000,"hot_memory");int st;ck(waitpid(child,&st,0)==child&&WIFEXITED(st)&&WEXITSTATUS(st)==0,"file child successful exit");child=0;double elapsed=now()-began;if(!memory_event)memory_event=notified(mem,0,hot?"hot_memory_after_read":"cold_memory_after_read");struct stats after=stats(g);struct pressure mem_after=pressure(g,"memory"),io_after=pressure(g,"io");ck(after.pgscan==before.pgscan&&after.pgsteal==before.pgsteal&&after.max_event==before.max_event,"no reclaim or memory.max enforcement during measurement");ck(mem_after.some>=mem_before.some&&mem_after.full>=mem_before.full,"memory PSI monotonic");ck(io_after.some>io_before.some&&io_after.full>io_before.full,"file IO PSI some/full grows");ck(elapsed>2.0&&elapsed<15.0,"file read actually throttled");unsigned long long md=mem_after.some-mem_before.some,fd=mem_after.full-mem_before.full;printf("LAB_REFAULT_MEASURE kind=%s expectation=%s memory_some_delta=%llu memory_full_delta=%llu io_some_delta=%llu io_full_delta=%llu refault_delta=%llu activate_delta=%llu pgscan_delta=%llu max_event_delta=%llu memory_event=%d seconds=%.3f\n",hot?"hot":"cold",expected_hooks?"hooks":"baseline",md,fd,io_after.some-io_before.some,io_after.full-io_before.full,after.refault-before.refault,after.activate-before.activate,after.pgscan-before.pgscan,after.max_event-before.max_event,memory_event,elapsed);if(hot){ck(after.refault>before.refault&&after.activate>before.activate,"hot refault restores active workingset");if(expected_hooks)ck(md>=20000&&memory_event,"hot refault counted as memory pressure and notified");else ck(md<=1000&&!memory_event,"old kernel hot refault has negligible memory PSI");}else ck(md<=1000&&!memory_event,"cold IO does not become memory PSI");close(mem);close(io);ck(!rmdir(g),"remove phase cgroup");}
int main(int argc,char **argv){if(argc!=2||(!getenv("PSI_REFAULT_QEMU_PROBE"))||access("/QEMU_LAB_GUEST",F_OK))return 125;if(!strcmp(argv[1],"--expect-hooks"))expected_hooks=1;else if(strcmp(argv[1],"--baseline"))return 125;setbuf(stdout,NULL);signal(SIGALRM,watchdog);alarm(60);struct stat image;ck(!stat(IMAGE,&image)&&image.st_size==100663296,"96MiB guest loop image guard");int fd=open(DEVICE,O_RDONLY);ck(fd>=0,"loop guard");struct loop_info64 li;ck(!ioctl(fd,LOOP_GET_STATUS64,&li)&&li.lo_inode==image.st_ino&&li.lo_offset==0,"loop backing file guard");close(fd);struct statfs fs;ck(!statfs("/files",&fs)&&fs.f_type==0xef53,"ext4 filesystem guard");group_put("/sys/fs/cgroup/unified","cgroup.subtree_control","+memory");ck(!mkdir(CG,0700)&&!mkdir(BLK,0700),"parent cgroups");group_put(CG,"cgroup.subtree_control","+memory");run_phase(0);run_phase(1);ck(!rmdir(CG)&&!rmdir(BLK),"remove parent cgroups");alarm(0);printf("LAB_REFAULT_PASS expectation=%s cold_hot_file_read_with_no_measurement_reclaim\n",expected_hooks?"hooks":"baseline");puts("PSI_REFAULT_PROBE_COMPLETE");return 0;}
